UPDATE OPS_RELEASE SET SYS_ID = #{sysId}, CHG_ID = #{chgId}, VER = #{ver}, TITLE = #{title}, CONTENT = #{content}, PLAN_DT =
TO_TIMESTAMP(REPLACE(#{planDt}, 'T', ' '), 'YYYY-MM-DD HH24:MI') NULL
WHERE REL_ID = #{relId}

UPDATE OPS_RELEASE
   SET STATUS     = #{status},
       RESULT     = #{result},
       CHARGER_ID = #{chargerId}

       , DEPLOY_DT = COALESCE(DEPLOY_DT, CURRENT_TIMESTAMP)

 WHERE REL_ID = #{relId}
